// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    GoodCallee good;

    function setUp() public { 
        c = new C();
        good = new GoodCallee();
    }

    // fuzzed params: from address, v amount, and dynamic length for _tos by supplying one address and a length
    function testFuzz_property(address from, address toAddr, uint256 v, uint256 len) public {
        // keep len reasonable but allow zero which should be rejected by require
        uint256 n = bound(len, 0, 8);

        // build an array of addresses of length n; if n==0 the call reverts in both versions
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            // use the same callee address (good) for all entries but allow fuzzer to supply a different base address
            tos[i] = address(good);
        }

        // We will call transfer and observe its returned boolean via try/catch to handle revert case.
        bool okRef;
        try c.transfer(from, address(good), tos, v) returns (bool ret) {
            okRef = ret;
        } catch {
            okRef = false;
        }

        // The general property: when transfer does not revert, the reference implementation returns true.
        // So assert that okRef is true whenever the call would not revert. For the mutant, some inputs will
        // produce a non-reverting call but return false, causing this assertion to fail.
        // To detect that, we require that if n>0 then the call should return true on the correct contract.
        // (If n==0 the call reverts by require and okRef==false; we allow that.)
        if (n > 0) {
            assertTrue(okRef);
        } else {
            // when n==0 both versions revert; ensure we saw a revert (okRef == false)
            assertTrue(!okRef);
        }
    }
}

// Minimal helper callee that implements transferFrom(address,address,uint256) and always succeeds
contract GoodCallee {
    event Transferred(address from, address to, uint256 v);
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        emit Transferred(from, to, v);
        return true;
    }
}

