pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: attacker address is produced by deploying a helper; we still fuzz value and number of tos
    function testFuzz_property(uint256 v, uint256 tosLen) public {
        // keep tosLen in a reasonable but wide bound: at least 1 to satisfy require, up to small bound
        tosLen = bound(tosLen, 1, 5);
        // Deploy a callee that will fail the very first call but succeed afterwards.
        AdversarialCallee adv = new AdversarialCallee();

        // Build _tos array: fill with distinct addresses (can reuse adv for all entries)
        address[] memory tos = new address[](tosLen);
        for (uint i = 0; i < tosLen; i++) tos[i] = address(adv);

        bool okRef;
        // Call reference contract and capture whether it returns true (or reverts)
        try c.transfer(address(0xBEEF), address(adv), tos, v) returns (bool r) {
            okRef = r;
        } catch {
            // If it reverts, set okRef to false
            okRef = false;
        }

        // The universal property: the reference contract always returns true (i.e., okRef == true)
        // for all admissible inputs (non-empty tos). The mutant which returns first call's success
        // can make this false when the first call fails. We assert that reference did return true.
        assertTrue(okRef);
    }
}

// Adversarial callee: fails on the first call to mimic a failing first external call, then succeeds.
contract AdversarialCallee {
    bool public firstCallDone;
    // match selector transferFrom(address,address,uint256)
    fallback() external payable returns (bytes memory) {
        if (!firstCallDone) {
            firstCallDone = true;
            revert("first call fails");
        }
        // succeed silently for subsequent calls
        return "";
    }
}

