pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: the from address, an arbitrary uint value, and the length of the _tos array (as uint)
    // We cannot fuzz raw addresses for adversarial behavior, so we will deploy a helper callee whose behaviour
    // can be controlled by the fuzzed index: we will construct an array of helper addresses where the first
    // element may be a Reverter (makes the first low-level call fail), others succeed. The deciding values
    // (whether first call fails) are produced by the fuzzed `firstShouldRevert` boolean via the fuzzed uint.
    function testFuzz_property(address from, uint256 v, uint256 tosLenRaw) public {
        // keep tos length in a reasonable non-zero range
        uint256 tosLen = bound(tosLenRaw, 1, 5);

        // Decide adversarial behaviour via a derived boolean from v: whether the first callee should revert
        bool firstShouldRevert = (v % 2 == 0);

        // Build the _tos array of addresses: first is either Reverter or GoodCallee; others are GoodCallee
        address[] memory tos = new address[](tosLen);
        for (uint i = 0; i < tosLen; i++) {
            if (i == 0) {
                if (firstShouldRevert) {
                    Reverter r = new Reverter();
                    tos[i] = address(r);
                } else {
                    GoodCallee g = new GoodCallee();
                    tos[i] = address(g);
                }
            } else {
                GoodCallee g = new GoodCallee();
                tos[i] = address(g);
            }
        }

        // Make the external calls. We only observe the overall transfer success (did it revert or not)
        bool ok;
        try c.transfer(from, address(this), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: The reference implementation, when it completes (does not revert), always returns true.
        // We assert that if the call completed (ok == true), then the return value would be true. Because we
        // cannot get the return value directly from try without capturing it, we instead re-call via low-level
        // call to obtain the returned boolean value to assert it equals true. This still observes c via its
        // external behaviour.

        if (ok) {
            // perform a low-level staticcall-like invocation to get the returned bool from transfer.
            // We call transfer again with same args and decode the returned bool. If the contract is the mutant,
            // this will sometimes return false (when first call failed), breaking the assertion.
            (bool s, bytes memory ret) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, address(this), tos, v));
            // If the external call reverts (s == false), that contradicts ok; ensure consistent
            // but main rule is: when it succeeds, the returned boolean must be true for the reference.
            if (s) {
                // decode returned bool
                bool returned = abi.decode(ret, (bool));
                assertTrue(returned);
            } else {
                // Inconsistent: first attempt succeeded but second low-level call reverted; treat as failure
                // to be conservative: fail the test
                assertTrue(false);
            }
        } else {
            // If the call reverted, nothing to assert about the return value; the reference can revert for some inputs.
            // To keep the property universal only over completed calls, we do not assert here.
            assertTrue(true);
        }
    }
}

// Helper that always reverts on any call
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
}

// Helper that simulates a successful transferFrom call
contract GoodCallee {
    fallback() external payable {}
    // provide transferFrom selector handler to accept the encoded call
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

