pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an address 'from', a uint 'v', and number of tos (length)
    // We will deploy a helper callee that fails on the first call only (so the first call returns false)
    // but subsequent calls succeed (so the overall transfer does not revert).
    function testFuzz_property(address from, uint256 v, uint256 tosLen) public {
        // keep tosLen moderate but allow zero handled by vm.assume
        tosLen = bound(tosLen, 1, 6); // _tos must be >0; keep small arrays for gas

        // Deploy a helper that fails on the first call and succeeds subsequently.
        FlakyFirstCall callee = new FlakyFirstCall();

        // Build the _tos array: we only need distinct addresses; use the test contract for subsequent successes
        address[] memory tos = new address[](tosLen);
        for (uint i = 0; i < tosLen; i++) {
            // route all calls to the same callee which implements behavior based on an index encoded in calldata
            tos[i] = address(callee);
        }

        // Prepare call: call c.transfer(from, address(callee), tos, v)
        // Capture its returned boolean via try/catch
        bool ok;
        try c.transfer(from, address(callee), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // If it reverts, we consider that the property is not applicable; but on the reference it should not revert here
            ok = false;
        }

        // General rule: reference C always returns true when it completes; mutant can return false when first external call fails.
        // Assert that c.transfer(...) returns true for all admissible inputs (non-empty _tos and our callee setup).
        assertTrue(ok);
    }
}

// Adversarial helper: fails (returns false) on the first low-level call that encodes selector transferFrom(...) and
// returns true on subsequent calls. It does NOT revert, so the outer loop in C will not revert.
contract FlakyFirstCall {
    bool public calledOnce = false;
    // emulate the target function selector: transferFrom(address,address,uint256)
    // We respond with a boolean success encoded in returndata: for the first call we return false (0), later true (1).
    fallback() external payable returns (bytes memory) {
        bytes memory ret;
        if (!calledOnce) {
            calledOnce = true;
            // return abi.encode(false)
            ret = abi.encode(false);
        } else {
            // return abi.encode(true)
            ret = abi.encode(true);
        }
        return ret;
    }
}

