pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: an address that will be used as the callee (we'll deploy helpers and pass their addresses),
    // and the number of _tos entries (must be >=1). We let the fuzzer pick tosCount and an arbitrary seed for which
    // helper to use; we map the seed to either a reverter or a conditional-failing callee.
    function testFuzz_property(uint8 tosCount, uint256 helperSelector) public {
        // keep domain wide but ensure at least one recipient
        uint256 n = bound(tosCount, 1, 10);

        // Prepare _tos array with n distinct addresses (can be arbitrary EOAs)
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            // generate some pseudo-random addresses via keccak
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(helperSelector, i, block.timestamp)))));
        }

        // Choose adversarial callee: either one that returns false on first call and true on others,
        // or one that reverts on first call but succeeds on others. The mutant reacts to the first call's success boolean.
        address callee;
        if (helperSelector % 2 == 0) {
            // FailingFirstOnce returns false (low-level call returns false) on first call, true afterwards
            FailingFirstOnce hf = new FailingFirstOnce();
            callee = address(hf);
        } else {
            // ReverterFirst reverts on first call, then returns normally on subsequent calls
            ReverterFirst hr = new ReverterFirst();
            callee = address(hr);
        }

        // Now call transfer and capture whether it returns true when it does not revert.
        bool ok;
        try c.transfer(address(this), callee, tos, 1) returns (bool ret) {
            // The reference implementation always returns true (when not reverted)
            ok = ret;
        } catch {
            // If it reverts, we consider that not completing; the universal property concerns calls that complete.
            // Set ok = false to make the assertion fail if the call reverts (but reference should not revert for these helpers).
            ok = false;
        }

        // Assert the universal property: for any admissible input (non-empty tos), the reference C.transfer (correct
        // version) returns true when it completes. This is the one assertion required. The mutant (which returns the
        // first call success flag) will be falsified for some inputs (e.g., when the first external call fails or reverts
        // but the overall transfer does not revert in reference), so the fuzzer can find such inputs.
        assertTrue(ok);
    }
}

// Helper that returns false on the first call (simulates a callee where low-level call returns (false, data))
contract FailingFirstOnce {
    bool public called;
    // fallback matches the low-level call signature and returns nothing; we craft behavior by returning 0/1 success
    fallback() external payable {
        if (!called) {
            called = true;
            // Do nothing but ensure the call appears to fail to the caller by reverting low-level? Low-level call returning
            // false cannot be produced by reverting (revert makes call return false to caller). To simulate a low-level
            // failure without consuming all gas, we revert here so the low-level call in caller receives success=false.
            revert("first fail");
        }
        // subsequent calls: do nothing (succeed with empty return)
    }
}

// Helper that reverts on first call, then succeeds on subsequent calls
contract ReverterFirst {
    bool public called;
    fallback() external payable {
        if (!called) {
            called = true;
            revert("first revert");
        }
        // succeed thereafter
    }
}

