        // admissible domain: must have at least one recipient as required by C; keep wide
        vm.assume(nTos > 0);
        // bound badIndex to be within array length
        uint256 len = bound(nTos, 1, 10); // keep arrays reasonably small
        uint256 idx = bound(badIndex, 0, uint8(len - 1));

        // deploy an adversarial callee that fails only on the first addressed recipient call
        ReverterFirstOnly reverter = new ReverterFirstOnly();

        // build tos array: place the reverter at position 0 to simulate first call failing
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            // fill with some EOA-like addresses except put the adversary at index 0
            if (i == 0) tos[i] = address(reverter);
            else tos[i] = address(uint160(uint(keccak256(abi.encodePacked(i, block.timestamp, from)))));
